//! The typed extension handles for Swift and Kotlin, generated from the
//! same metadata the Rust commands check their arguments against, so the
//! platform signatures cannot drift from them.
//!
//! This test fails when a generated file is out of date. Regenerate both:
//!
//! ```sh
//! CANVIST_UPDATE_HANDLES=1 cargo test -p canvist_ffi --test handles
//! ```

use std::fmt::Write;
use std::path::Path;
use std::path::PathBuf;

use serde_json::Value as Json;

/// Extensions every editor registers. Only paragraphs have commands.
const CORE: [&str; 4] = ["doc", "paragraph", "baseKeymap", "undoInputRule"];

const HEADER: &str = "// Generated by `crates/canvist_ffi/tests/handles.rs` from the \
                      extension\n// metadata. Do not edit; regenerate with\n// \
                      `CANVIST_UPDATE_HANDLES=1 cargo test -p canvist_ffi --test handles`.\n";

/// The StarterKit's metadata, sorted by extension name.
fn metadata() -> Vec<Json> {
	let names: Vec<String> = canvist_ffi::EditorOptions::starter_kit().extensions;
	let json = canvist_ffi::extension_metadata(names).expect("the StarterKit is valid");
	let mut extensions: Vec<Json> = serde_json::from_str(&json).expect("metadata is JSON");
	extensions.sort_by(|a, b| name(a).cmp(name(b)));
	extensions
}

fn name(json: &Json) -> &str {
	json["name"].as_str().expect("every item has a name")
}

fn list<'a>(json: &'a Json, key: &str) -> &'a [Json] {
	json[key].as_array().map_or(&[], Vec::as_slice)
}

fn pascal(name: &str) -> String {
	let mut characters = name.chars();
	characters.next().map_or_else(String::new, |first| {
		first.to_uppercase().chain(characters).collect()
	})
}

/// `" From 1 to 6."` or `" One of a, b."`, from a value type's range.
fn range(kind: &Json) -> String {
	if let (Some(min), Some(max)) = (kind.get("min"), kind.get("max")) {
		return format!(" From {min} to {max}.");
	}

	kind.get("enum")
		.and_then(Json::as_array)
		.map(|values| {
			let values: Vec<&str> = values.iter().filter_map(Json::as_str).collect();
			format!(" One of {}.", values.join(", "))
		})
		.unwrap_or_default()
}

/// The extensions with handles: every optional one, and paragraphs.
fn with_handles(extensions: &[Json]) -> impl Iterator<Item = &Json> {
	extensions
		.iter()
		.filter(|extension| !CORE.contains(&name(extension)) || name(extension) == "paragraph")
}

fn optional(extensions: &[Json]) -> impl Iterator<Item = &Json> {
	extensions
		.iter()
		.filter(|extension| !CORE.contains(&name(extension)))
}

mod swift {
	use super::*;

	fn kind(json: &Json) -> String {
		match json["type"].as_str() {
			Some("bool") => "Bool".to_owned(),
			Some("int") => "Int".to_owned(),
			Some("float") => "Double".to_owned(),
			Some("string") => "String".to_owned(),
			Some("nullable") => format!("{}?", kind(&json["of"])),
			other => panic!("unknown value type {other:?}"),
		}
	}

	fn decoder(json: &Json) -> String {
		match json["type"].as_str() {
			Some("bool") => "Decode.bool".to_owned(),
			Some("int") => "Decode.int".to_owned(),
			Some("float") => "Decode.double".to_owned(),
			Some("string") => "Decode.string".to_owned(),
			Some("nullable") => format!("Decode.optional({})", decoder(&json["of"])),
			other => panic!("unknown value type {other:?}"),
		}
	}

	fn case(json: &Json) -> &'static str {
		match json["type"].as_str() {
			Some("bool") => "bool",
			Some("int") => "int",
			Some("float") => "double",
			Some("string") => "string",
			Some("nullable") => case(&json["of"]),
			other => panic!("unknown value type {other:?}"),
		}
	}

	fn command(out: &mut String, command: &Json) {
		let args = list(command, "args");
		writeln!(
			out,
			"    /// {}",
			command["doc"].as_str().unwrap_or_default()
		)
		.ok();

		if !args.is_empty() {
			writeln!(out, "    ///").ok();
		}

		for arg in args {
			let doc = arg["doc"].as_str().unwrap_or_default();
			writeln!(
				out,
				"    /// - Parameter {}: {doc}{}",
				name(arg),
				range(&arg["type"])
			)
			.ok();
		}

		let params: Vec<String> = args
			.iter()
			.map(|arg| {
				let optional = arg.get("default").is_some();
				let kind = kind(&arg["type"]);
				let kind = if optional && !kind.ends_with('?') {
					format!("{kind}?")
				} else {
					kind
				};
				let default = if optional { " = nil" } else { "" };
				format!("{}: {kind}{default}", name(arg))
			})
			.collect();
		let values: Vec<String> = args
			.iter()
			.map(|arg| {
				let case = case(&arg["type"]);
				let value = if arg.get("default").is_some() || arg["type"]["type"] == "nullable" {
					format!("{}.map(ArgumentValue.{case})", name(arg))
				} else {
					format!(".{case}({})", name(arg))
				};
				format!("\"{}\": {value}", name(arg))
			})
			.collect();
		let args = if values.is_empty() {
			String::new()
		} else {
			format!(", [{}]", values.join(", "))
		};

		writeln!(
			out,
			"    public func {}({}) -> Command {{\n        command(\"{}\"{args})\n    }}\n",
			name(command),
			params.join(", "),
			name(command),
		)
		.ok();
	}

	fn query(out: &mut String, query: &Json) {
		let returns = &query["returns"];
		writeln!(
			out,
			"    /// {}\n    public func {}() -> Query<{}> {{\n        Query(\"{}\", decode: \
			 {})\n    }}\n",
			query["doc"].as_str().unwrap_or_default(),
			name(query),
			kind(returns),
			name(query),
			decoder(returns),
		)
		.ok();
	}

	fn handle(out: &mut String, extension: &Json) {
		let pascal = pascal(name(extension));
		writeln!(
			out,
			"/// The commands and queries of `{}`.\npublic struct {pascal}Handle: Sendable {{\n    init() {{}}\n",
			name(extension)
		)
		.ok();

		for item in list(extension, "commands") {
			command(out, item);
		}

		for item in list(extension, "queries") {
			query(out, item);
		}

		while out.ends_with("\n\n") {
			out.pop();
		}

		out.push_str("}\n\n");
	}

	pub(super) fn render(extensions: &[Json]) -> String {
		let mut out = format!("{HEADER}\n");

		for extension in with_handles(extensions) {
			handle(&mut out, extension);
		}

		out.push_str(
			"/// Every StarterKit extension, to pass to `ExtensionSet.add`.\npublic enum \
			 Extensions {\n",
		);

		for extension in optional(extensions) {
			let name = name(extension);
			writeln!(
				out,
				"    /// The `{name}` extension.\n    public static let {name} = Extension(name: \
				 \"{name}\", handle: {}Handle())\n",
				pascal(name)
			)
			.ok();
		}

		out.pop();
		out.push_str(
			"}\n\n/// Handles for every StarterKit extension, all registered.\npublic struct \
			 StarterKit: Sendable {\n    /// The extensions to give an editor.\n    public let \
			 extensions: ExtensionSet\n    /// Paragraphs.\n    public let paragraph = \
			 ParagraphHandle()\n",
		);

		for extension in optional(extensions) {
			let name = name(extension);
			writeln!(
				out,
				"    /// `{name}`.\n    public let {name}: {}Handle",
				pascal(name)
			)
			.ok();
		}

		out.push_str(
			"\n    /// Register every StarterKit extension.\n    public init() {\n        var \
			 extensions = ExtensionSet()\n",
		);

		for extension in optional(extensions) {
			let name = name(extension);
			writeln!(out, "        {name} = extensions.add(Extensions.{name})").ok();
		}

		out.push_str("        self.extensions = extensions\n    }\n}\n");
		out
	}
}

mod kotlin {
	use super::*;

	fn kind(json: &Json) -> String {
		match json["type"].as_str() {
			Some("bool") => "Boolean".to_owned(),
			Some("int") => "Int".to_owned(),
			Some("float") => "Double".to_owned(),
			Some("string") => "String".to_owned(),
			Some("nullable") => format!("{}?", kind(&json["of"])),
			other => panic!("unknown value type {other:?}"),
		}
	}

	fn decoder(json: &Json) -> String {
		match json["type"].as_str() {
			Some("bool") => "Decode::bool".to_owned(),
			Some("int") => "Decode::int".to_owned(),
			Some("float") => "Decode::double".to_owned(),
			Some("string") => "Decode::string".to_owned(),
			Some("nullable") => format!("Decode.optional({})", decoder(&json["of"])),
			other => panic!("unknown value type {other:?}"),
		}
	}

	fn command(out: &mut String, command: &Json) {
		let args = list(command, "args");
		let doc = command["doc"].as_str().unwrap_or_default();

		if args.is_empty() {
			writeln!(out, "    /** {doc} */").ok();
		} else {
			writeln!(out, "    /**\n     * {doc}\n     *").ok();

			for arg in args {
				let doc = arg["doc"].as_str().unwrap_or_default();
				writeln!(
					out,
					"     * @param {} {doc}{}",
					name(arg),
					range(&arg["type"])
				)
				.ok();
			}

			out.push_str("     */\n");
		}

		let params: Vec<String> = args
			.iter()
			.map(|arg| {
				let optional = arg.get("default").is_some();
				let kind = kind(&arg["type"]);
				let kind = if optional && !kind.ends_with('?') {
					format!("{kind}?")
				} else {
					kind
				};
				let default = if optional { " = null" } else { "" };
				format!("{}: {kind}{default}", name(arg))
			})
			.collect();
		let values: Vec<String> = args
			.iter()
			.map(|arg| format!("\"{0}\" to {0}", name(arg)))
			.collect();
		let args = if values.is_empty() {
			String::new()
		} else {
			format!(", mapOf({})", values.join(", "))
		};

		writeln!(
			out,
			"    fun {}({}): Command = command(\"{}\"{args})\n",
			name(command),
			params.join(", "),
			name(command),
		)
		.ok();
	}

	fn query(out: &mut String, query: &Json) {
		let returns = &query["returns"];
		writeln!(
			out,
			"    /** {} */\n    fun {}(): Query<{}> = Query(\"{}\", {})\n",
			query["doc"].as_str().unwrap_or_default(),
			name(query),
			kind(returns),
			name(query),
			decoder(returns),
		)
		.ok();
	}

	fn handle(out: &mut String, extension: &Json) {
		let pascal = pascal(name(extension));
		writeln!(
			out,
			"/** The commands and queries of `{}`. */\nclass {pascal}Handle internal \
			 constructor() {{",
			name(extension)
		)
		.ok();

		for item in list(extension, "commands") {
			command(out, item);
		}

		for item in list(extension, "queries") {
			query(out, item);
		}

		while out.ends_with("\n\n") {
			out.pop();
		}

		out.push_str("}\n\n");
	}

	pub(super) fn render(extensions: &[Json]) -> String {
		let mut out = format!("{HEADER}\npackage io.github.ifiokjr.canvist\n\n");

		for extension in with_handles(extensions) {
			handle(&mut out, extension);
		}

		out.push_str(
			"/** Every StarterKit extension, to pass to [ExtensionSet.add]. */\nobject Extensions \
			 {\n",
		);

		for extension in optional(extensions) {
			let name = name(extension);
			writeln!(
				out,
				"    /** The `{name}` extension. */\n    val {name} = Extension(\"{name}\", \
				 {}Handle())\n",
				pascal(name)
			)
			.ok();
		}

		out.pop();
		out.push_str(
			"}\n\n/** Handles for every StarterKit extension, all registered. */\nclass \
			 StarterKit {\n    /** The extensions to give an editor. */\n    val extensions = \
			 ExtensionSet()\n\n    /** Paragraphs. */\n    val paragraph = ParagraphHandle()\n",
		);

		for extension in optional(extensions) {
			let name = name(extension);
			writeln!(
				out,
				"\n    /** `{name}`. */\n    val {name} = extensions.add(Extensions.{name})"
			)
			.ok();
		}

		out.push_str("}\n");
		out
	}
}

fn platforms() -> PathBuf {
	PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../platforms")
}

/// Compare `generated` with the file at `path`, or write it there when
/// `CANVIST_UPDATE_HANDLES` is set.
fn check(path: &Path, generated: &str) {
	if std::env::var_os("CANVIST_UPDATE_HANDLES").is_some() {
		std::fs::write(path, generated).expect("the platform directory is writable");
		return;
	}

	let committed = std::fs::read_to_string(path).unwrap_or_default();
	assert!(
		committed == generated,
		"{} is out of date; run `CANVIST_UPDATE_HANDLES=1 cargo test -p canvist_ffi --test \
		 handles`",
		path.display()
	);
}

#[test]
fn swift_handles_are_up_to_date() {
	check(
		&platforms().join("apple/Sources/Canvist/Extensions.generated.swift"),
		&swift::render(&metadata()),
	);
}

#[test]
fn kotlin_handles_are_up_to_date() {
	check(
		&platforms().join(
			"android/canvist/src/main/kotlin/io/github/ifiokjr/canvist/Extensions.generated.kt",
		),
		&kotlin::render(&metadata()),
	);
}
